import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Stream from 'flarum/common/utils/Stream';
import GroupBadge from 'flarum/common/components/GroupBadge';
/**
 * Config UI for the builtin `group` rule type.
 *
 * Rule config shape: { groupIds: number[] }
 */
export default class GroupListConfig extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    const cfg = this.attrs.config || {};
    let initial = [];
    if (Array.isArray(cfg.groupIds)) initial = cfg.groupIds.map(id => parseInt(String(id), 10));
    this.groupIds = Stream(initial);
  }
  view() {
    return m("div", {
      className: "FilterRuleManager-ConfigForm"
    }, m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('huoxin-filter-rule-manager.admin.config_groups_label')), m("div", {
      className: "helpText"
    }, app.translator.trans('huoxin-filter-rule-manager.admin.config_groups_help')), m("div", {
      className: "FilterRuleManager-RulesetEditor-groupSelection"
    }, app.store.all('groups').map(group => {
      const id = parseInt(String(group.id()), 10);
      const isActive = (this.groupIds() || []).includes(id);
      return m("label", {
        className: `FilterRuleManager-RulesetEditor-groupOption ${isActive ? 'active' : ''}`,
        key: id
      }, m("input", {
        type: "checkbox",
        checked: isActive,
        onchange: e => {
          const checked = e.target.checked;
          let current = this.groupIds() || [];
          if (checked) {
            current.push(id);
          } else {
            current = current.filter(g => g !== id);
          }
          this.groupIds(current);
          this.attrs.onchange({
            ...(this.attrs.config || {}),
            groupIds: current
          });
        }
      }), m("div", {
        className: "FilterRuleManager-RulesetEditor-groupOption-content"
      }, m(GroupBadge, {
        group: group,
        label: ""
      }), m("span", {
        className: "FilterRuleManager-RulesetEditor-groupOption-name"
      }, String(group.namePlural() || group.name()))));
    }))));
  }
}
flarum.reg.add('huoxin-filter-rule-manager', 'admin/components/config/GroupListConfig', GroupListConfig);