import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
export default class WordCountConfig extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    const config = this.attrs.config || {};
    this.min = config.min !== undefined ? String(config.min) : '';
    this.max = config.max !== undefined ? String(config.max) : '';
  }
  view() {
    return m("div", {
      className: "FilterRuleManager-ConfigForm"
    }, m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('huoxin-filter-rule-manager.admin.config_word_count_min')), m("input", {
      className: "FormControl",
      type: "number",
      min: "0",
      value: this.min,
      oninput: e => this.updateConfig('min', e.target.value),
      placeholder: "e.g. 10"
    })), m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('huoxin-filter-rule-manager.admin.config_word_count_max')), m("input", {
      className: "FormControl",
      type: "number",
      min: "1",
      value: this.max,
      oninput: e => this.updateConfig('max', e.target.value),
      placeholder: "e.g. 500"
    })), m("div", {
      className: "helpText"
    }, app.translator.trans('huoxin-filter-rule-manager.admin.config_word_count_help')));
  }
  updateConfig(key, value) {
    const config = {
      ...(this.attrs.config || {})
    };
    if (key === 'min' || key === 'max') {
      if (value === '') {
        delete config[key];
      } else {
        config[key] = parseInt(value, 10);
      }
    } else {
      config[key] = value;
    }

    // Also update local state so UI reflects
    if (key === 'min') this.min = value;
    if (key === 'max') this.max = value;
    this.attrs.onchange(config);
  }
}
flarum.reg.add('huoxin-filter-rule-manager', 'admin/components/config/WordCountConfig', WordCountConfig);